-- Ledger 864 (owner: milk logged on its own counts toward the dairy step).
-- Generated by drizzle-kit, wholly additive: one NOT NULL column with a
-- constant DEFAULT (Postgres fills existing rows from the default without a
-- rewrite). No row is changed: every existing tag reads false, so counting is
-- exactly 0022's until the seeds set whole milk -> Milk to true (a cup of
-- milk counts; milk that is an ingredient of one of the meal's recipes still
-- doesn't). Butter and sesame oil stay false.
ALTER TABLE "food_allergens" ADD COLUMN "counts_when_alone" boolean DEFAULT false NOT NULL;
